// One output item per PDF attachment, with the email context attached.
const cfg = $('Config').first().json;
const allowed = String(cfg.allowedSenderDomains || '')
  .split(',').map((d) => d.trim().toLowerCase()).filter(Boolean);

const out = [];
for (const email of $('Watch invoice inbox').all()) {
  const from = email.json.from?.value?.[0]?.address || email.json.from?.text || '';
  const domain = (from.split('@')[1] || '').toLowerCase();
  if (allowed.length && !allowed.includes(domain)) continue;

  for (const [key, file] of Object.entries(email.binary || {})) {
    const isPdf = /pdf/i.test(file.mimeType || '') || /\.pdf$/i.test(file.fileName || '');
    if (!isPdf) continue;
    out.push({
      json: {
        received_at: new Date(email.json.date || Date.now()).toISOString(),
        from,
        subject: email.json.subject || '',
        file_name: file.fileName || key,
      },
      binary: { data: file },
    });
  }
}
return out;

// Layout-tolerant invoice field extraction from the PDF text layer.
const cfg = $('Config').first().json;
const meta = $('Collect PDF attachments').all();
const SYMBOLS = { '$': 'USD', '€': 'EUR', '£': 'GBP', '¥': 'JPY', '₹': 'INR' };
const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
const pad = (n) => String(n).padStart(2, '0');

function toNumber(raw) {
  if (!raw) return null;
  let s = raw.replace(/[\s\u00a0']/g, '');
  const lastComma = s.lastIndexOf(','), lastDot = s.lastIndexOf('.');
  if (lastComma > lastDot) s = s.replace(/\./g, '').replace(',', '.');   // 1.234,56
  else s = s.replace(/,/g, '');                                           // 1,234.56
  const n = Number(s);
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : null;
}

function toIsoDate(raw) {
  if (!raw) return '';
  let m = raw.match(/(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})/);
  if (m) return `${m[1]}-${pad(m[2])}-${pad(m[3])}`;
  m = raw.match(/(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2,4})/);
  if (m) {
    let [a, b, y] = [Number(m[1]), Number(m[2]), Number(m[3])];
    if (y < 100) y += 2000;
    // Day-first unless that is impossible; set "usDates" in Config to prefer month-first.
    let day = a, month = b;
    if (cfg.usDates === true) { day = b; month = a; }
    if (month > 12) { [day, month] = [month, day]; }
    return `${y}-${pad(month)}-${pad(day)}`;
  }
  m = raw.match(/([A-Za-z]{3,9})\.?\s+(\d{1,2}),?\s+(\d{4})/);
  if (m && MONTHS[m[1].slice(0, 3).toLowerCase()]) return `${m[3]}-${pad(MONTHS[m[1].slice(0, 3).toLowerCase()])}-${pad(m[2])}`;
  m = raw.match(/(\d{1,2})\s+([A-Za-z]{3,9})\.?\s+(\d{4})/);
  if (m && MONTHS[m[2].slice(0, 3).toLowerCase()]) return `${m[3]}-${pad(MONTHS[m[2].slice(0, 3).toLowerCase()])}-${pad(m[1])}`;
  return '';
}

const DATE = String.raw`(\d{4}[-\/.]\d{1,2}[-\/.]\d{1,2}|\d{1,2}[-\/.]\d{1,2}[-\/.]\d{2,4}|[A-Za-z]{3,9}\.?\s+\d{1,2},?\s+\d{4}|\d{1,2}\s+[A-Za-z]{3,9}\.?\s+\d{4})`;
const AMOUNT = String.raw`([A-Z]{3}|[$€£¥₹])?\s*(-?\d{1,3}(?:[\s.,'\u00a0]\d{3})*(?:[.,]\d{1,2})?|-?\d+(?:[.,]\d{1,2})?)\s*([A-Z]{3}|[$€£¥₹])?`;

return $input.all().map((item, i) => {
  const src = meta[i]?.json || {};
  const text = String(item.json.text || '').replace(/\r/g, '');
  const lines = text.split('\n').map((l) => l.trim()).filter(Boolean);
  const find = (re) => { const m = text.match(re); return m ? m[1].trim() : ''; };

  const invoice_number = find(/invoice\s*(?:no\.?|number|num\.?|#|id)\s*[:#.]?\s*([A-Z0-9][A-Z0-9\-\/_.]{1,30})/i)
    || find(/\b(INV[-_\/]?[A-Z0-9\-\/]{2,})/i);
  const invoice_date = toIsoDate(find(new RegExp(String.raw`(?:invoice\s+date|date\s+of\s+issue|issue\s+date|issued(?:\s+on)?|date)\s*[:\-]?\s*` + DATE, 'i')));
  const due_date = toIsoDate(find(new RegExp(String.raw`(?:due\s+date|payment\s+due|due\s+by|due)\s*[:\-]?\s*` + DATE, 'i')));

  // Prefer the most specific total label, else the last "Total" line that is not a subtotal.
  let total = null, currency = '';
  const labels = [/(?:total\s+due|amount\s+due|balance\s+due|grand\s+total|total\s+to\s+pay|amount\s+payable)/i, /\btotal(?:\s*\((?:incl\.?|including)[^)\n]*\))?/i];
  for (const label of labels) {
    const hits = lines.filter((l) => label.test(l) && /\d/.test(l) && !/sub[\s-]?total|tax\s+total|vat\s+total/i.test(l));
    if (!hits.length) continue;
    const m = hits[hits.length - 1].replace(label, ' ').match(new RegExp(AMOUNT));
    if (m) { total = toNumber(m[2]); const cur = m[1] || m[3] || ''; currency = SYMBOLS[cur] || cur; break; }
  }
  if (!currency) {
    const iso = text.match(/\b(USD|EUR|GBP|CAD|AUD|CHF|JPY|INR|SGD|NZD)\b/);
    const sym = text.match(/[$€£¥₹]/);
    currency = iso ? iso[1] : sym ? SYMBOLS[sym[0]] : cfg.defaultCurrency;
  }

  let vendor = find(/(?:^|\n)\s*(?:from|vendor|supplier|seller|bill(?:ed)?\s+from)\s*[:\-]\s*([^\n]+)/i);
  if (!vendor) vendor = lines.find((l) => !/invoice|^date|^page|^\d/i.test(l)) || '';
  vendor = vendor.replace(/\s{2,}.*/, '').slice(0, 120);

  const missing = [!vendor && 'vendor', !invoice_number && 'invoice_number', total === null && 'total'].filter(Boolean);
  return {
    json: {
      received_at: src.received_at || '',
      from: src.from || '',
      subject: src.subject || '',
      file_name: src.file_name || '',
      vendor,
      invoice_number,
      invoice_date,
      due_date,
      currency,
      total: total === null ? '' : total,
      status: missing.length ? `needs review (missing: ${missing.join(', ')})` : 'parsed',
    },
  };
});
